(() => {
'use strict';
const {schools,nodes,edges,disciplines}=window.ATLAS;
const $=s=>document.querySelector(s);
const el=(tag,cls,text)=>{const x=document.createElement(tag);if(cls)x.className=cls;if(text!==undefined)x.textContent=text;return x};
const types={inherit:'继承 / 发展',critique:'批判',fork:'分化',dialogue:'跨科对话'};
const colors={inherit:'#6f9183',critique:'#b46b66',fork:'#9c885f',dialogue:'#587b9a'};
let school='all',discipline='all',selected='waltz',zoom=1;
const byId=id=>nodes.find(n=>n.id===id), schoolInfo=id=>schools.find(s=>s[0]===id);
$('#total').textContent=nodes.length;
$('#rangeLabel').textContent='SELECTED WORKS · '+Math.min(...nodes.map(n=>n.year))+'—'+Math.max(...nodes.map(n=>n.year));
function fieldNodes(){return nodes.filter(n=>discipline==='all'||n.disciplines.includes(discipline))}
function readNote(id){try{return localStorage.getItem('alkaid:note:'+id)||''}catch{return ''}}
function saveNote(id,text){try{localStorage.setItem('alkaid:note:'+id,text);return true}catch{return false}}
function resetFilters(){school='all';$('#search').value='';$('#era').value='all';$('#level').value='all'}
function selectNode(id,focus=false){selected=id;renderDetail();document.querySelectorAll('.node').forEach(b=>{const active=b.dataset.id===id;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',String(active))});document.querySelectorAll('.edge').forEach(p=>{const active=p.dataset.from===id||p.dataset.to===id;p.setAttribute('stroke-width',active?'2.5':'1');p.style.opacity=active?'1':'.24'});if(focus&&innerWidth<1151){$('#detail').scrollIntoView({behavior:'smooth',block:'start'});$('#detail h2').focus({preventScroll:true})}}
function renderDisciplines(){const wrap=$('#disciplineFilters');wrap.replaceChildren();disciplines.forEach(([id,label],i)=>{const b=el('button','discipline'+(discipline===id?' active':''));b.append(el('span','discipline-number',id==='all'?'◎':'0'+i),el('strong','',label),el('span','discipline-count',nodes.filter(n=>id==='all'||n.disciplines.includes(id)).length));b.setAttribute('aria-pressed',String(discipline===id));b.onclick=()=>{discipline=id;resetFilters();renderDisciplines();renderSchools();renderGraph();$('#graphScroll').scrollTo(0,0)};wrap.append(b)});$('#mapTitle').textContent=disciplines.find(d=>d[0]===discipline)[1]}
function renderSchools(){const wrap=$('#schoolFilters'),pool=fieldNodes();wrap.replaceChildren();[['all','全部分支','#174f43'],...schools.filter(s=>pool.some(n=>n.school===s[0]))].forEach(([id,label,color])=>{const b=el('button','school'+(school===id?' active':''));b.style.setProperty('--school',color);b.append(el('span','dot'),el('span','',label),el('span','count',id==='all'?pool.length:pool.filter(n=>n.school===id).length));b.setAttribute('aria-pressed',String(school===id));b.onclick=()=>{school=id;renderSchools();renderGraph();$('#graphScroll').scrollTo(0,0)};wrap.append(b)})}
function matching(){const q=$('#search').value.trim().toLocaleLowerCase(),era=$('#era').value,level=$('#level').value;return fieldNodes().filter(n=>(school==='all'||n.school===school)&&(level==='all'||n.level===level)&&(era==='all'||era==='early'&&n.year<1900||era==='pre'&&n.year>=1900&&n.year<1950||era==='mid'&&n.year>=1950&&n.year<1980||era==='late'&&n.year>=1980&&n.year<2000||era==='new'&&n.year>=2000)&&[n.name,n.title,n.book,n.intro,n.claim,n.year,schoolInfo(n.school)[1],...(window.ACADEMIC_I18N?.[n.id]||[])].join(' ').toLocaleLowerCase().includes(q))}
function renderGraph(){
 const filtered=matching(),graph=$('#graph');graph.replaceChildren();$('#resultCount').textContent=filtered.length+' / '+fieldNodes().length+' NODES';$('#empty').hidden=filtered.length>0;$('#graphScroll').hidden=!filtered.length;
 if(!filtered.length){$('#detail').replaceChildren(el('div','detail-inner','没有匹配的节点。重置筛选后继续探索。'));window.dispatchEvent(new Event('atlas:graph'));return}
 if(!filtered.some(n=>n.id===selected))selected=filtered[0].id;
 const activeSchools=schools.filter(s=>filtered.some(n=>n.school===s[0])),positions=new Map();let maxCount=1;
 activeSchools.forEach(([id,label,color],row)=>{const list=filtered.filter(n=>n.school===id).sort((a,b)=>a.year-b.year);maxCount=Math.max(maxCount,list.length);const lane=el('div','lane',label+'  /  '+list.length);lane.style.top=(row*178*zoom)+'px';lane.style.height=178*zoom+'px';lane.style.setProperty('--school',color);graph.append(lane);list.forEach((n,col)=>positions.set(n.id,{x:(24+col*226)*zoom,y:(row*178+39)*zoom}))});
 const width=Math.max(650,(maxCount*226+30)*zoom),height=activeSchools.length*178*zoom+20;graph.style.width=width+'px';graph.style.height=height+'px';
 const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');svg.setAttribute('width',width);svg.setAttribute('height',height);svg.setAttribute('aria-hidden','true');const defs=document.createElementNS(ns,'defs');
 Object.entries(colors).forEach(([type,color])=>{const marker=document.createElementNS(ns,'marker');marker.id='arrow-'+type;for(const [k,v] of Object.entries({viewBox:'0 0 10 10',refX:'9',refY:'5',markerWidth:'5',markerHeight:'5',orient:'auto'}))marker.setAttribute(k,v);const path=document.createElementNS(ns,'path');path.setAttribute('d','M 0 0 L 10 5 L 0 10 z');path.setAttribute('fill',color);marker.append(path);defs.append(marker)});svg.append(defs);
 edges.forEach(e=>{const a=positions.get(e.from),b=positions.get(e.to);if(!a||!b)return;const p=document.createElementNS(ns,'path'),x1=a.x+190*zoom,y1=a.y+53*zoom,x2=b.x,y2=b.y+53*zoom;let d;if(x2>x1){const bend=Math.max(25,(x2-x1)*.45);d='M'+x1+','+y1+' C'+(x1+bend)+','+y1+' '+(x2-bend)+','+y2+' '+x2+','+y2}else{const gutter=Math.max(x1,b.x+190*zoom)+18*zoom;d='M'+x1+','+y1+' C'+gutter+','+y1+' '+gutter+','+(y2-65*zoom)+' '+(x2+95*zoom)+','+(y2-65*zoom)+' L'+(x2+95*zoom)+','+(b.y)}
 p.setAttribute('d',d);p.classList.add('edge');p.dataset.from=e.from;p.dataset.to=e.to;p.setAttribute('fill','none');p.setAttribute('stroke',colors[e.type]);p.setAttribute('marker-end','url(#arrow-'+e.type+')');if(e.type!=='inherit')p.setAttribute('stroke-dasharray',e.type==='critique'?'6 4':e.type==='fork'?'2 4':'8 3 2 3');svg.append(p)});graph.append(svg);
 filtered.forEach(n=>{const p=positions.get(n.id),b=el('button','node');b.dataset.id=n.id;b.style.left=p.x+'px';b.style.top=p.y+'px';b.style.transformOrigin='top left';b.style.scale=String(zoom);b.style.setProperty('--school',schoolInfo(n.school)[2]);b.setAttribute('aria-label',n.name+'，'+n.title+'，'+n.year);b.append(el('time','',n.year),el('strong','',n.name),el('small','',n.title.split(' · ').pop()));b.onclick=()=>selectNode(n.id,true);graph.append(b)});selectNode(selected);window.dispatchEvent(new Event('atlas:graph'));
}
function jumpTo(id){const target=byId(id);if(discipline!=='all'&&!target.disciplines.includes(discipline))discipline='all';resetFilters();selected=id;renderDisciplines();renderSchools();renderGraph();document.querySelector('[data-id="'+id+'"]')?.scrollIntoView({behavior:'smooth',block:'nearest',inline:'center'})}
function renderDetail(){const n=byId(selected),s=schoolInfo(n.school),aside=$('#detail');aside.replaceChildren();aside.style.setProperty('--school',s[2]);aside.append(el('div','detail-top'));const box=el('div','detail-inner');box.append(el('span','tag',s[1]+' / SELECTED NODE'));const heading=el('h2','',n.name);heading.tabIndex=-1;box.append(heading,el('div','subtitle',n.title));const meta=el('div','meta');meta.append(el('span','',n.year+' · 代表作'),el('span','',n.level));box.append(meta,el('p','node-intro',n.intro),el('h3','','核心命题'),el('p','claim',n.claim),el('h3','','代表作'),el('cite','book',n.book));const link=el('a','source',n.sourceType+' ↗');link.href=n.url;link.target='_blank';link.rel='noopener noreferrer';box.append(link);
 const related=edges.filter(e=>e.from===n.id||e.to===n.id);box.append(el('h3','','思想关系 · '+related.length));const ul=el('ul','relations');if(!related.length)ul.append(el('li','','尚未编入关系，后续继续补充。'));related.forEach(e=>{const other=byId(e.from===n.id?e.to:e.from),li=el('li'),button=el('button','',(e.from===n.id?'→ ':'← ')+other.name+' · '+types[e.type]);button.onclick=()=>jumpTo(other.id);li.append(button,el('p','',e.note));ul.append(li)});box.append(ul);renderNotes(box,n.id);aside.append(box);aside.scrollTop=0;window.dispatchEvent(new CustomEvent('atlas:detail',{detail:n}))
}
function renderNotes(box,id){const label=el('h3','','我的阅读笔记'),input=el('textarea','note-input');input.setAttribute('aria-label','我的阅读笔记');input.placeholder='记录疑问、引文页码与下一步阅读…';input.value=readNote(id);const status=el('span','note-status','仅保存在当前浏览器');status.setAttribute('role','status');input.oninput=()=>{status.textContent=saveNote(id,input.value)?'已自动保存到本机':'浏览器存储不可用，请导出笔记'};const actions=el('div','note-actions'),save=el('button','','保存笔记'),download=el('button','','导出笔记 ↓');save.onclick=()=>{status.textContent=saveNote(id,input.value)?'已保存到本机':'无法保存，请导出笔记'};download.onclick=()=>{const content='# '+byId(id).name+'\n\n'+input.value+'\n',url=URL.createObjectURL(new Blob([content],{type:'text/markdown;charset=utf-8'})),a=el('a');a.href=url;a.download=id+'-notes.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};actions.append(save,download);box.append(label,input,status,actions)}
function changeView(view){document.querySelectorAll('.tab').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);b.setAttribute('aria-pressed',String(b.dataset.view===view))});['atlas','profile','about'].forEach(v=>$('#'+v+'View').hidden=v!==view)}
function renderProfile(){const p=window.PROFILE;$('#profileName').textContent=p.name;$('#profileIntro').textContent=p.intro;$('#aboutBio').textContent=p.intro;if(p.portrait){const img=el('img');img.src=p.portrait;img.alt=p.name+'的照片';$('#portrait').replaceChildren(img)}else{$('#portrait').append(el('span','photo-pending','照片待补充'))}
 [['education',p.education],['experience',p.experience]].forEach(([id,items])=>{const parent=$('#'+id);parent.replaceChildren();if(!items.length){parent.append(el('p','pending','内容整理中。'));return}items.forEach(item=>{const row=el('article','bio-item');if(item.logo){const image=el('img','school-logo');image.src=item.logo;image.alt=item.title+'校徽';image.loading='lazy';row.append(image)}const copy=el('div');copy.append(el('h3','',item.title));if(item.detail)copy.append(el('p','',item.detail));if(item.years)copy.append(el('span','bio-years',item.years));row.append(copy);parent.append(row)})})}
document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>changeView(b.dataset.view));$('#goProfile').onclick=()=>changeView('profile');
['search','era','level'].forEach(id=>$('#'+id).addEventListener(id==='search'?'input':'change',renderGraph));
$('#reset').onclick=()=>{discipline='all';resetFilters();selected='waltz';renderDisciplines();renderSchools();renderGraph();$('#graphScroll').scrollTo(0,0)};
function setZoom(v){zoom=Math.min(1.5,Math.max(.85,v));$('#fit').textContent=Math.round(zoom*100)+'%';renderGraph()}
$('#zoomIn').onclick=()=>setZoom(zoom+.15);$('#zoomOut').onclick=()=>setZoom(zoom-.15);$('#fit').onclick=()=>setZoom(1);$('#method').onclick=()=>$('#about').showModal();$('#closeAbout').onclick=()=>$('#about').close();
window.ATLAS_APP={selectNode,jumpTo,renderGraph};
renderDisciplines();renderSchools();renderGraph();renderProfile();changeView('atlas');
})();
